SELECT variant_get(data, '$.commit.collection', 'string') AS event, count(*) AS count FROM bluesky GROUP BY event ORDER BY count DESC;
SELECT variant_get(data, '$.commit.collection', 'string') AS event, count(*) AS count, count(DISTINCT variant_get(data, '$.did', 'string')) AS users FROM bluesky WHERE variant_get(data, '$.kind', 'string') = 'commit' AND variant_get(data, '$.commit.operation', 'string') = 'create' GROUP BY event ORDER BY count DESC;
SELECT variant_get(data, '$.commit.collection', 'string') AS event, hour(timestamp_micros(variant_get(data, '$.time_us', 'bigint'))) AS hour_of_day, count(*) AS count FROM bluesky WHERE variant_get(data, '$.kind', 'string') = 'commit' AND variant_get(data, '$.commit.operation', 'string') = 'create' AND variant_get(data, '$.commit.collection', 'string') IN ('app.bsky.feed.post', 'app.bsky.feed.repost', 'app.bsky.feed.like') GROUP BY event, hour_of_day ORDER BY hour_of_day, event;
SELECT variant_get(data, '$.did', 'string') AS user_id, min(timestamp_micros(variant_get(data, '$.time_us', 'bigint'))) AS first_post_ts FROM bluesky WHERE variant_get(data, '$.kind', 'string') = 'commit' AND variant_get(data, '$.commit.operation', 'string') = 'create' AND variant_get(data, '$.commit.collection', 'string') = 'app.bsky.feed.post' GROUP BY user_id ORDER BY first_post_ts ASC LIMIT 3;
SELECT variant_get(data, '$.did', 'string') AS user_id, timestampdiff(MILLISECOND, min(timestamp_micros(variant_get(data, '$.time_us', 'bigint'))), max(timestamp_micros(variant_get(data, '$.time_us', 'bigint')))) AS activity_span FROM bluesky WHERE variant_get(data, '$.kind', 'string') = 'commit' AND variant_get(data, '$.commit.operation', 'string') = 'create' AND variant_get(data, '$.commit.collection', 'string') = 'app.bsky.feed.post' GROUP BY user_id ORDER BY activity_span DESC LIMIT 3;
